import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"BedrockAddonManager","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/index.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/index.md","filePath":"packages/bedrock-addon-manager/docs/index.md","lastUpdated":1792508854000}`),l={name:`packages/bedrock-addon-manager/docs/index.md`},u={id:`bedrockaddonmanager`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`BedrockAddonManager `),n(`a`,{class:`header-anchor`,href:`#bedrockaddonmanager`,"aria-label":`Permalink to “BedrockAddonManager”`},`​`)],-1),n(`span`,d,[a(h,{type:`info`,text:`v0.0.0`})])]),c[1]||=r(`<p>BedrockAddonManager scans Bedrock <code>.mcpack</code> and <code>.mcaddon</code> files, reads their manifests, and serves enabled resource packs over HTTP. <code>/baddon export</code> prints the <code>pumpkin.toml</code> block that makes Pumpkin offer those packs to Bedrock players when they join; see <a href="./setup#offer-the-packs-to-players">Offer the packs to players</a>.</p><h2 id="typical-setup" tabindex="-1">Typical setup <a class="header-anchor" href="#typical-setup" aria-label="Permalink to “Typical setup”">​</a></h2><p>Install <code>bedrock-addon-manager.wasm</code> in the server&#39;s <code>plugins/</code> directory and start or restart the server. Put pack files in <code>plugins/data/BedrockAddonManager/packs/</code>, then run <code>/baddon reload</code> to scan them. Use <code>/baddon list</code> to see discovered packs and their effective settings. The plugin keeps its configuration in its own data folder.</p><p>Choose a URL Bedrock clients can reach. Set <code>web.public_url</code> when serving packs through a known address or reverse proxy. If it is empty, <code>web.bind</code> is <code>0.0.0.0</code>, and you set <code>web.port_forwarding = true</code>, the plugin asks UPnPumpkin to forward <code>web.port</code>. If forwarding does not succeed, it uses a loopback address that works only on the server machine. See <a href="./setup">setup</a> for network and pack-format details, or <a href="./troubleshooting">troubleshooting</a> if clients cannot download a pack.</p><h2 id="pack-selection" tabindex="-1">Pack selection <a class="header-anchor" href="#pack-selection" aria-label="Permalink to “Pack selection”">​</a></h2><p>The plugin reads each pack&#39;s <code>manifest.json</code> for its UUID, version, and flags. An <code>.mcaddon</code> may contain both behavior and resource packs; only the resource packs are extracted and served. Per-file overrides can disable a pack, change its order, or provide an external <code>download_url</code>. For packs extracted from an <code>.mcaddon</code>, use the effective name shown by <code>/baddon list</code> as the override key.</p><p>The built-in server uses plain HTTP. Put a TLS reverse proxy in front of it when clients need an HTTPS URL, or host the files elsewhere and configure download URLs.</p>`,7)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};